def brute_force_max_m(N):
    import itertools
    def get_compositions(n, min_val=1):
        if n == 0:
            yield []
            return
        for i in range(min_val, n + 1):
            for rest in get_compositions(n - i, 1):
                yield [i] + rest
    max_m = 0
    for comp in get_compositions(N):
        m = 0
        for i in range(len(comp) - 2):
            m += comp[i] * comp[i+1] * comp[i+2]
        if m > max_m:
            max_m = m
    return max_m

for n in range(3, 21):
    print(f"N={n}, max_m={brute_force_max_m(n)}")

def local_search_v2(N, k):
    if k == 3:
        counts = [N // 3] * 3
        for i in range(N % 3):
            counts[i] += 1
    elif k == 4:
        counts = [N // 4] * 4
        for i in range(N % 4):
            counts[i] += 1
    else:
        # Try the strategy: c1=1, ck=1, and others are roughly (N-2)/(k-2)
        counts = [1] * k
        remaining = N - k
        for i in range(1, k-1):
            counts[i] += remaining // (k-2)
        for i in range(1, k-1 + remaining % (k-2)):
            counts[i] += 1

    current_m = get_m(counts)

    improved = True
    while improved:
        improved = False
        for i in range(k):
            for j in range(k):
                if i != j and counts[i] > 1:
                    counts[i] -= 1
                    counts[j] += 1
                    new_m = get_m(counts)
                    if new_m > current_m:
                        current_m = new_m
                        improved = True
                        break
                    else:
                        counts[i] += 1
                        counts[j] -= 1
            if improved:
                break
    return current_m

for k in range(3, 21):
    print(f"k={k}, max_m={local_search_v2(2025, k)}")
